-- A venue's tag list (brief S3-06, D60): `tags`. Generated by drizzle-kit, then edited by hand:
-- row-level security and the updated_at trigger appended. Privileges come from src/table-access.ts.
CREATE TABLE "restro"."tags" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"label" jsonb NOT NULL,
	"color" text NOT NULL,
	"sort_key" text COLLATE "C" NOT NULL,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tags_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "tags_id_format" CHECK ("restro"."tags"."id" ~ '^tg_[0-9A-Za-z]+$'),
	CONSTRAINT "tags_label_object" CHECK (jsonb_typeof("restro"."tags"."label") = 'object' and "restro"."tags"."label" <> '{}'::jsonb),
	CONSTRAINT "tags_color_format" CHECK ("restro"."tags"."color" ~ '^[a-z][a-z0-9_]{0,31}$'),
	CONSTRAINT "tags_sort_key_format" CHECK ("restro"."tags"."sort_key" ~ '^[A-Za-z][0-9A-Za-z]*$')
);
